class ListNode:
    def __init__(self, val, nxt=None):
        self.val = val
        self.next = nxt

def build(values):
    # Python list -> linked nodes, built from the tail so each node points forward.
    head = None
    for val in reversed(values):
        head = ListNode(val, head)
    return head

def to_list(head):
    # Linked nodes -> Python list, head to tail.
    values = []
    while head is not None:
        values.append(head.val)
        head = head.next
    return values

def solution(head):
    prev = None
    cur = build(head)
    while cur is not None:
        nxt = cur.next       # save the rest of the list
        cur.next = prev      # turn this pointer round
        prev = cur           # slide both pointers one step forward
        cur = nxt
    return to_list(prev)     # prev is the old tail, now the head

