class ListNode:
    def __init__(self, val, nxt=None):
        self.val = val
        self.next = nxt

def build(values):
    # Python list -> linked nodes, built from the tail so each node points forward.
    head = None
    for val in reversed(values):
        head = ListNode(val, head)
    return head

def to_list(head):
    # Linked nodes -> Python list, head to tail.
    values = []
    while head is not None:
        values.append(head.val)
        head = head.next
    return values

def solution(head):
    # Repeatedly walk to the tail, unhook it and append it to the result.
    # Each walk is O(n), so this is O(n^2).
    first = build(head)
    out = []
    while first is not None:
        if first.next is None:
            out.append(first.val)
            first = None
            continue
        before = first
        while before.next.next is not None:
            before = before.next
        out.append(before.next.val)
        before.next = None
    return out
